import React, {useEffect, useMemo, useState} from 'react';
import {createRoot} from 'react-dom/client';
import {Bell, ChevronDown, ChevronLeft, CircleHelp, ClipboardList, FileText, FolderKanban, LayoutDashboard, MoreHorizontal, PanelLeftClose, Plus, Search, Settings, Sparkles, Target, Users, X, CheckCircle2, CircleDot, Flag, Calendar, Upload, Send, Bot, SlidersHorizontal, BarChart3, ListTodo, Layers, Menu, MessageSquare, Paperclip, ArrowUpRight} from 'lucide-react';
import './styles.css';
