type Status='To Do'|'In Progress'|'Submit Work'|'Documentation Review'|'Done';
type DocStatus='Not Started'|'Work Submitted'|'Generating'|'Needs Review'|'Approved';
type Dependency={type:'blocks'|'blockedBy'|'relatesTo',issueId:string};
type WorkSubmission={summary:string,evidence:string[],aiPrompt?:string,documentStructure?:string,customSections?:string,repository?:string,branch?:string,pullRequest?:string,submittedAt?:string};
type Task={id:string,title:string,status:Status,priority:'Highest'|'High'|'Medium'|'Low',assignee:string,initials:string,points:number,labels:string[],doc:DocStatus,description:string,epic:string,project?:string,submission?:WorkSubmission,dependencies?:Dependency[]};
const seed:Task[]=[
 {id:'AIH-102',title:'Implement Google OAuth authentication',status:'In Progress',priority:'High',assignee:'Ahmed',initials:'AH',points:5,labels:['authentication','backend'],doc:'Work Submitted',epic:'Authentication',description:'Implement secure OAuth sign-in and account linking with Google for the platform.',dependencies:[{type:'blockedBy',issueId:'AIH-109'}]},
 {id:'AIH-108',title:'Design workspace invitation flow',status:'To Do',priority:'Medium',assignee:'Sara',initials:'SA',points:3,labels:['design','onboarding'],doc:'Not Started',epic:'Workspace',description:'Create the invitation experience for administrators and new team members.'},
 {id:'AIH-109',title:'Add session refresh token rotation',status:'In Progress',priority:'Highest',assignee:'Omar',initials:'OM',points:8,labels:['security','api'],doc:'Needs Review',epic:'Authentication',description:'Add rotation and expiry validation for all refresh sessions.'},
 {id:'AIH-110',title:'Create audit-log event schema',status:'Documentation Review',priority:'High',assignee:'Lina',initials:'LI',points:5,labels:['database','api'],doc:'Needs Review',epic:'Platform',description:'Define events, retention and query patterns for audit history.',dependencies:[{type:'blocks',issueId:'AIH-115'}]},
 {id:'AIH-111',title:'Build project activity timeline',status:'Done',priority:'Medium',assignee:'Yousef',initials:'YO',points:3,labels:['frontend'],doc:'Approved',epic:'Workspace',description:'Expose meaningful project activity in a concise timeline.',submission:{summary:'Built the activity timeline UI, added activity event formatting, and covered loading and empty states.',evidence:['activity-timeline-before-after.mp4','timeline-component.tsx','activity-empty-state.png'],repository:'aih/platform',branch:'feature/activity-timeline',pullRequest:'#142 Activity timeline',submittedAt:'2026-10-06T09:30:00.000Z'}},
 {id:'AIH-112',title:'Configure rate limiting middleware',status:'Submit Work',priority:'High',assignee:'Ahmed',initials:'AH',points:5,labels:['security','backend'],doc:'Not Started',epic:'Platform',description:'Protect public API endpoints with tiered request limits.'},
 {id:'AIH-113',title:'Mobile navigation accessibility pass',status:'To Do',priority:'Low',assignee:'Sara',initials:'SA',points:2,labels:['accessibility','frontend'],doc:'Not Started',epic:'Mobile',description:'Audit keyboard and screen reader paths across mobile navigation.'},
 {id:'AIH-114',title:'Refactor notification preferences',status:'Done',priority:'Medium',assignee:'Lina',initials:'LI',points:5,labels:['frontend','settings'],doc:'Approved',epic:'Workspace',description:'Allow granular per-channel notification preference controls.',submission:{summary:'Refactored notification preferences into reusable controls and added validation for every delivery channel.',evidence:['notification-settings.png','notification-preferences.tsx','preference-test-results.pdf'],repository:'aih/platform',branch:'refactor/notification-preferences',pullRequest:'#151 Notification preferences',submittedAt:'2026-10-05T14:10:00.000Z'}},
 {id:'AIH-115',title:'Add webhook delivery retries',status:'Documentation Review',priority:'High',assignee:'Omar',initials:'OM',points:8,labels:['api','reliability'],doc:'Generating',epic:'Platform',description:'Implement exponential retry queue and delivery observability.'},
 {id:'AIH-116',title:'Fix duplicate member import',status:'To Do',priority:'High',assignee:'Yousef',initials:'YO',points:3,labels:['bug','backend'],doc:'Not Started',epic:'Workspace',description:'Prevent duplicate memberships during bulk CSV import.'},
];
const columns:Status[]=['To Do','In Progress','Submit Work','Documentation Review','Done'];
const Icon=({children}:{children:React.ReactNode})=><span className="nav-icon">{children}</span>;
function Avatar({name,initials}:{name:string,initials:string}){return <span className={'avatar a'+initials[0]} title={name}>{initials}</span>}
function Badge({children,kind='' }:{children:React.ReactNode,kind?:string}){return <span className={'badge '+kind}>{children}</span>}
async function api<T>(path:string, options?:RequestInit):Promise<T>{const res=await fetch('/api'+path,{headers:{'Content-Type':'application/json'},...options});if(!res.ok)throw new Error('Request failed');return res.json()}
function App(){
 const [tasks,setTasks]=useState<Task[]>(seed),[page,setPage]=useState('My work'),[collapsed,setCollapsed]=useState(false),[query,setQuery]=useState(''),[selected,setSelected]=useState<Task|null>(null),[create,setCreate]=useState(false),[notify,setNotify]=useState(false),[submission,setSubmission]=useState<Task|null>(null),[doc,setDoc]=useState<Task|null>(null),[dragId,setDragId]=useState<string|null>(null),[toast,setToast]=useState(''),[project,setProject]=useState('AI H Platform');
 const projects=['AI H Platform','E-Commerce System','Mobile Banking','Internal Tools'];
 const projectFor=(task:Task)=>task.project||({ 'AIH-102':'AI H Platform','AIH-108':'Internal Tools','AIH-109':'AI H Platform','AIH-110':'AI H Platform','AIH-111':'Internal Tools','AIH-112':'AI H Platform','AIH-113':'Mobile Banking','AIH-114':'Internal Tools','AIH-115':'E-Commerce System','AIH-116':'E-Commerce System'}[task.id]||'AI H Platform');
 useEffect(()=>{api<Task[]>('/tasks').then(data=>setTasks(data.map(t=>({...t,project:projectFor(t)})))).catch(()=>setToast('API unavailable — using local data'))},[]);
 const filtered=useMemo(()=>tasks.filter(t=>(t.title+t.id+t.assignee+t.labels.join(' ')).toLowerCase().includes(query.toLowerCase())),[tasks,query]);
 const persist=(id:string,patch:Partial<Task>)=>api<Task>('/tasks/'+id,{method:'PATCH',body:JSON.stringify(patch)}).then(updated=>{setTasks(a=>a.map(t=>t.id===id?updated:t));setSelected(s=>s?.id===id?updated:s);return updated});
 const move=(id:string,status:Status)=>{const task=tasks.find(t=>t.id===id);const blockers=(task?.dependencies||[]).filter(d=>d.type==='blockedBy').map(d=>tasks.find(t=>t.id===d.issueId)).filter((t):t is Task=>Boolean(t&&t.status!=='Done'));if(status==='Done'&&blockers.length){setToast(`Blocked by ${blockers.map(t=>t.id).join(', ')}. Complete prerequisite work first.`);return}persist(id,{status}).then(()=>{setToast('Issue moved to '+status);setTimeout(()=>setToast(''),1800)}).catch(()=>setToast('Could not save issue'))};
 const action=(event:React.MouseEvent<HTMLDivElement>)=>{const button=(event.target as HTMLElement).closest('button');if(!button)return;const label=(button.textContent||'').trim();if(!label)return;
   if(label.includes('New document')||button.classList.contains('add-card')){setCreate(true);setToast('Issue form opened.');return}
   if(label.includes('Create project')){const name=window.prompt('Project name');if(name)setToast(`${name} project created locally.`);return}
   if(label.includes('Create sprint')){const name=window.prompt('Sprint name');if(name)setToast(`${name} created locally.`);return}
   if(label.includes('Start sprint')){setToast('Sprint 12 is already active.');return}
   if(label.includes('Add comment')){const comment=window.prompt('Add a comment');if(comment)setToast('Comment added to this issue.');return}
   if(label.includes('Add')&&label.includes('Attachments')){setToast('Attachment picker opened.');return}
   if(['Filter','Assignee','Priority','Labels','Group','Sort','Columns','All types','Status','Last modified','All projects'].some(x=>label.includes(x))){setToast(`${label.replace(/⌄|⌘/g,'').trim()} menu opened.`);return}
   if(label.includes('View all notifications')){setNotify(false);setPage('Your work');setToast('Showing your work and notifications.');return}
   if(label.includes('Export')){const blob=new Blob(['AI H documentation export'],{type:'text/plain'});const href=URL.createObjectURL(blob);const a=document.createElement('a');a.href=href;a.download='aih-documentation.txt';a.click();URL.revokeObjectURL(href);setToast('Documentation exported.');return}
   if(label.includes('Share')){navigator.clipboard?.writeText(window.location.href);setToast('Documentation link copied to clipboard.');return}
   if(label.includes('More'))setToast('More actions are available for this item.');
 };
 const nav=[['My work',<ClipboardList/>],['Projects',<FolderKanban/>],['Search',<Search/>]];
 const projectNav=[['Issues',<ListTodo/>],['Board',<Layers/>],['Backlog',<ClipboardList/>],['Sprints',<Flag/>],['Documentation',<FileText/>],['Project settings',<Settings/>]];
 return <div className={'app '+(collapsed?'collapsed':'')} onClick={action}>
  <aside className="sidebar"><div className="brand"><div className="brand-mark">AI</div>{!collapsed&&<><b>AI H</b><span className="beta">BETA</span></>}</div><button className="collapse" onClick={()=>setCollapsed(!collapsed)}>{collapsed?<Menu/>:<PanelLeftClose/>}</button>
   <nav>{nav.map(([n,i])=><button className={page===n?'active':''} onClick={()=>setPage(n as string)} key={n as string}><Icon>{i}</Icon>{!collapsed&&n}</button>)}</nav>
   {!collapsed&&<><div className="side-label">AI H PLATFORM</div><nav>{projectNav.map(([n,i])=><button className={page===n?'active':''} onClick={()=>setPage(n as string)} key={n as string}><Icon>{i}</Icon>{n}</button>)}</nav></>}
   <div className="sidebar-bottom"><button onClick={()=>setPage('Settings')}><Icon><Settings/></Icon>{!collapsed&&'Settings'}</button><div className="me"><Avatar name="Ahmed Hassan" initials="AH"/>{!collapsed&&<span><b>Ahmed Hassan</b><small>Product Engineer</small></span>}</div></div>
  </aside>
  <main><header><div className="crumb"><span>Projects</span><select className="header-project" value={project} onChange={e=>setProject(e.target.value)}>{projects.map(p=><option key={p}>{p}</option>)}</select></div><div className="top-actions"><button className="search-button" onClick={()=>setPage('Search')}><Search size={16}/> Search <kbd>⌘ K</kbd></button><button className="icon-btn" onClick={()=>setNotify(!notify)}><Bell size={18}/><i/></button><button className="icon-btn"><CircleHelp size={18}/></button><Avatar name="Ahmed Hassan" initials="AH"/></div>{notify&&<Notifications close={()=>setNotify(false)}/>}</header>
  {page==='Board'?<Board tasks={filtered} query={query} setQuery={setQuery} open={setSelected} onDrag={setDragId} move={move} dragId={dragId} submit={setSubmission}/>:page==='Sprints'?<Sprints tasks={tasks} open={setSelected}/>:page==='Documentation'?<Docs tasks={tasks} projects={projects} open={setDoc}/>:page==='Backlog'?<Backlog tasks={filtered} open={setSelected} create={()=>setCreate(true)}/>:page==='Projects'?<Projects open={(name)=>{setProject(name);setPage('Issues')}}/>:page==='Search'?<SearchPage tasks={filtered} query={query} setQuery={setQuery} open={setSelected}/>:page==='My work'||page==='Issues'?<WorkList tasks={page==='My work'?filtered.filter(t=>t.assignee==='Ahmed'):filtered} open={setSelected} create={()=>setCreate(true)} mine={page==='My work'} board={()=>setPage('Board')}/>:<Overview page="Settings" tasks={tasks} open={setSelected}/>} 
  </main>{selected&&<IssueDrawer task={selected} tasks={tasks} close={()=>setSelected(null)} submit={()=>{setSubmission(selected);setSelected(null)}} change={(p)=>persist(selected.id,p).catch(()=>setToast('Could not save issue'))}/>} {create&&<CreateModal close={()=>setCreate(false)} add={(t)=>{api<Task>('/tasks',{method:'POST',body:JSON.stringify({...t,project})}).then(created=>{setTasks(x=>[created,...x]);setCreate(false);setToast('Issue created')}).catch(()=>setToast('Could not create issue'))}}/>}{submission&&<Submission task={submission} close={()=>setSubmission(null)} generate={(t,work)=>{api<Task>('/tasks/'+t.id+'/submission',{method:'POST',body:JSON.stringify(work)}).then(()=>api<Task>('/tasks/'+t.id+'/generate-documentation',{method:'POST',body:JSON.stringify({aiInstructions:work.aiPrompt||'',documentStructure:work.documentStructure||'',customSections:work.customSections||''})})).then(updated=>{setTasks(ts=>ts.map(x=>x.id===t.id?updated:x));setSubmission(null);setDoc(updated)}).catch(()=>setToast('Could not generate documentation'))}}/>}{doc&&<DocumentEditor task={doc} close={()=>setDoc(null)} approve={()=>{api<Task>('/tasks/'+doc.id+'/approve-documentation',{method:'POST'}).then(updated=>{setTasks(ts=>ts.map(x=>x.id===doc.id?updated:x));setDoc(null);setToast('Documentation approved')}).catch(()=>setToast('Could not approve documentation'))}}/>}{toast&&<div className="toast"><CheckCircle2 size={17}/>{toast}</div>}
 </div>}
function Board({tasks,query,setQuery,open,onDrag,move,dragId,submit}:{tasks:Task[],query:string,setQuery:(x:string)=>void,open:(t:Task)=>void,onDrag:(x:string|null)=>void,move:(i:string,s:Status)=>void,dragId:string|null,submit:(t:Task)=>void}){const [assignees,setAssignees]=useState<string[]>([]);const people=Array.from(new Map(tasks.map(t=>[t.assignee,{name:t.assignee,initials:t.initials}])).values());const visible=assignees.length?tasks.filter(t=>assignees.includes(t.assignee)):tasks;const toggle=(name:string)=>setAssignees(current=>current.includes(name)?current.filter(x=>x!==name):[...current,name]);return <section className="content"><div className="page-head"><div><div className="eyebrow">AI H PLATFORM / SPRINT 12</div><h1>Active sprint board</h1><p>Authentication &amp; workspace foundations <Badge kind="blue">12 days remaining</Badge></p></div><div className="head-actions"><button className="secondary"><SlidersHorizontal size={16}/> Filters</button><button className="secondary">Group by <ChevronDown size={14}/></button></div></div><div className="sprint-strip"><div><b>Sprint 12</b><span>Goal: Ship a secure, scalable authentication experience</span></div><div className="progress"><span><b>64%</b> complete</span><div><i style={{width:'64%'}}/></div></div><div className="avatars"><Avatar name="Ahmed" initials="AH"/><Avatar name="Sara" initials="SA"/><Avatar name="Omar" initials="OM"/><Avatar name="Lina" initials="LI"/></div><MoreHorizontal size={19}/></div><div className="toolbar board-filterbar"><div className="inline-search"><Search size={16}/><input placeholder="Search board" value={query} onChange={e=>setQuery(e.target.value)}/></div><div className="assignee-filter"><span className="filter-person"><Users size={15}/></span>{people.map(person=><button className={'person-filter '+(assignees.includes(person.name)?'selected':'')} key={person.name} title={'Filter by '+person.name} aria-label={'Filter by '+person.name} onClick={()=>toggle(person.name)}><Avatar name={person.name} initials={person.initials}/></button>)}</div><button className={'filter-button '+(assignees.length?'active':'')}><SlidersHorizontal size={15}/> Filter {assignees.length>0&&<span>{assignees.length}</span>}</button>{assignees.length>0&&<button className="clear-filters" onClick={()=>setAssignees([])}>Clear filters</button>}<button className="secondary group-button"><Layers size={15}/> Group</button><span className="count">{visible.length} issues</span></div><div className="board">{columns.map(c=><div className="kanban-col" key={c} onDragOver={e=>e.preventDefault()} onDrop={()=>dragId&&move(dragId,c)}><div className="col-head"><b>{c}</b><span>{visible.filter(t=>t.status===c).length}</span><MoreHorizontal size={16}/></div><div className="card-stack">{visible.filter(t=>t.status===c).map(t=><TaskCard key={t.id} task={t} open={()=>open(t)} drag={()=>onDrag(t.id)} submit={()=>submit(t)}/>)}</div><button className="add-card"><Plus size={15}/> Create issue</button></div>)}</div></section>}
function TaskCard({task,open,drag,submit}:{task:Task,open:()=>void,drag:()=>void,submit:()=>void}){const blockers=(task.dependencies||[]).filter(d=>d.type==='blockedBy');return <article className="task-card" draggable onDragStart={drag} onClick={open}><div className="card-top"><span className="issue-key"><CircleDot size={14}/>{task.id}</span><Badge kind={'priority '+task.priority.toLowerCase()}>{task.priority}</Badge></div><h3>{task.title}</h3><div className="labels">{task.labels.map(x=><Badge key={x}>{x}</Badge>)}</div>{blockers.length>0&&<span className="dependency-card"><Layers size={12}/> Blocked by {blockers.map(d=>d.issueId).join(', ')}</span>}<div className="card-bottom"><div><Avatar name={task.assignee} initials={task.initials}/><span className="points">{task.points}</span></div><span className={'doc-state '+task.doc.toLowerCase().replaceAll(' ','-')}><Sparkles size={12}/>{task.doc}</span></div>{task.status==='Submit Work'&&<button className="submit-mini" onClick={e=>{e.stopPropagation();submit()}}>Submit work <ArrowUpRight size={13}/></button>}</article>}
function Overview({page,tasks,open}:{page:string,tasks:Task[],open:(t:Task)=>void}){if(page==='Settings')return <SettingsPage/>;
 return <section className="content"><div className="page-head"><div><div className="eyebrow">PROJECT OVERVIEW</div><h1>{page==='Summary'?'AI H Platform':page}</h1><p>{page==='Summary'?'A workspace for building the next generation of technical knowledge.':'Your work across AI H Platform.'}</p></div><button className="secondary"><Calendar size={16}/> Oct 7 – Oct 21</button></div><div className="summary-hero"><div><span className="project-icon">AH</span><h2>AI H Platform</h2><p>Central project management and documentation intelligence for modern engineering teams.</p><div className="member-row"><span>Project lead</span><Avatar name="Ahmed Hassan" initials="AH"/><b>Ahmed Hassan</b><em>·</em><span>8 members</span></div></div><div className="goal"><span>SPRINT 12 GOAL</span><b>Deliver secure authentication</b><p>12 days remaining</p><div className="progress"><div><i style={{width:'64%'}}/></div><small>64% complete</small></div></div></div><div className="stat-grid">{[['Open tasks','14','up 3 this week'],['In progress','6','2 due this week'],['Completed','42','85% sprint velocity'],['Documentation','38 / 42','90% coverage']].map(([a,b,c],i)=><div className="stat" key={a}><span>{a} {i===3&&<Sparkles size={14}/>}</span><b>{b}</b><small>{c}</small></div>)}</div><div className="dashboard-grid"><section className="panel"><div className="panel-head"><div><h2>Sprint progress</h2><p>Completion trend across Sprint 12</p></div><MoreHorizontal size={18}/></div><div className="chart"><div className="chart-lines">{[20,45,70,95].map(x=><i key={x} style={{bottom:x+'%'}}/>)}</div><svg viewBox="0 0 600 170" preserveAspectRatio="none"><path d="M0 26 C60 38 80 46 120 48 S185 70 220 72 S280 87 300 76 S360 108 395 102 S440 125 480 118 S535 142 600 150" fill="none" stroke="#2d65d7" strokeWidth="4"/><path d="M0 26 C60 38 80 46 120 48 S185 70 220 72 S280 87 300 76 S360 108 395 102 S440 125 480 118 S535 142 600 150 V170 H0Z" fill="url(#g)"/><defs><linearGradient id="g" x1="0" x2="0" y1="0" y2="1"><stop stopColor="#dbe7ff"/><stop offset="1" stopColor="#fff"/></linearGradient></defs></svg><div className="chart-labels"><span>Oct 7</span><span>Oct 10</span><span>Oct 14</span><span>Today</span><span>Oct 21</span></div></div></section><section className="panel"><div className="panel-head"><div><h2>Documentation health</h2><p>Keep knowledge current as work ships</p></div><Sparkles size={18}/></div><div className="doc-health"><div className="ring">90<small>%</small></div><div><b>Excellent coverage</b><p>38 approved · 3 in review · 1 pending</p><button className="link-btn">View documentation <ArrowUpRight size={14}/></button></div></div><div className="mini-bars">{['Generated','Approved','Edited'].map((x,i)=><div key={x}><span>{x}</span><i style={{width:(85-i*16)+'%'}}/></div>)}</div></section><section className="panel activity"><div className="panel-head"><div><h2>Recent activity</h2><p>Latest movement in your project</p></div><button className="link-btn">View all</button></div>{[['AH','Ahmed moved AIH-102 to In Progress','12 min ago'],['SA','Sara submitted work for AIH-108','1 hour ago'],['AI','AI generated OAuth documentation','2 hours ago'],['OM','Omar completed AIH-111','Yesterday']].map(([i,x,t])=><div className="activity-row" key={x}><Avatar name={i} initials={i}/><div><p><b>{x.split(' ')[0]}</b> {x.substring(x.indexOf(' ')+1)}</p><small>{t}</small></div></div>)}</section><section className="panel tasks-mini"><div className="panel-head"><div><h2>Priority issues</h2><p>Needs attention this sprint</p></div><MoreHorizontal size={18}/></div>{tasks.slice(0,4).map(t=><button key={t.id} onClick={()=>open(t)}><Badge kind="priority high">High</Badge><span><b>{t.id}</b> {t.title}</span><Avatar name={t.assignee} initials={t.initials}/></button>)}</section></div></section>}
type DocTemplate={id:string,name:string,bestFor:string,sections:string[]};
function DocumentationSettings(){const [templates,setTemplates]=useState<DocTemplate[]>([]),[selected,setSelected]=useState<DocTemplate|null>(null),[name,setName]=useState(''),[bestFor,setBestFor]=useState(''),[sections,setSections]=useState(['Overview','Purpose']),[notice,setNotice]=useState('');useEffect(()=>{api<DocTemplate[]>('/document-templates').then(data=>{setTemplates(data);setSelected(data[0]||null)}).catch(()=>setNotice('Could not load saved structures.'))},[]);const addSection=()=>setSections(current=>[...current,'New section']);const editSection=(index:number,value:string)=>setSections(current=>current.map((item,i)=>i===index?value:item));const removeSection=(index:number)=>setSections(current=>current.filter((_,i)=>i!==index));const saveStructure=()=>{const valid=sections.map(item=>item.trim()).filter(Boolean);if(!name.trim()||!valid.length){setNotice('Add a structure name and at least one section.');return}api<DocTemplate>('/document-templates',{method:'POST',body:JSON.stringify({name,bestFor,sections:valid})}).then(template=>{setTemplates(current=>[...current,template]);setSelected(template);setName('');setBestFor('');setSections(['Overview','Purpose']);setNotice('Custom structure saved for future submissions.')}).catch(()=>setNotice('Could not save structure.'))};return <div className="template-settings"><div className="template-intro"><h3>Document structures</h3><p>Employees choose a suitable structure when submitting work. Review each structure here and save reusable custom formats.</p></div><div className="template-workspace"><div className="template-list">{templates.map(template=><button className={selected?.id===template.id?'selected':''} onClick={()=>setSelected(template)} key={template.id}><FileText size={15}/><span><b>{template.name}</b><small>{template.bestFor}</small></span><ChevronDown size={14}/></button>)}</div><div className="template-preview">{selected&&<><span className="eyebrow">STRUCTURE PREVIEW</span><h3>{selected.name}</h3><p className="suitable"><CheckCircle2 size={15}/> Suitable for: {selected.bestFor}</p><ol>{selected.sections.map(section=><li key={section}>{section}</li>)}</ol><p className="template-note">This structure is available to employees in the completed-work submission flow.</p></>}</div></div><div className="custom-template"><div><h3>Create custom structure</h3><p>Build the outline exactly as employees should see it during work submission.</p></div><label>Name<input value={name} onChange={e=>setName(e.target.value)} placeholder="e.g. Quarterly client review"/></label><label>Best for<input value={bestFor} onChange={e=>setBestFor(e.target.value)} placeholder="e.g. Account management and renewals"/></label><div className="section-builder"><div className="builder-head"><b>Document sections</b><button className="secondary" onClick={addSection}><Plus size={14}/> Add section</button></div>{sections.map((section,index)=><div className="section-row" key={index}><span>{index+1}</span><input value={section} onChange={e=>editSection(index,e.target.value)} aria-label={'Section '+(index+1)}/><button className="remove-section" onClick={()=>removeSection(index)} disabled={sections.length===1} aria-label="Remove section"><X size={14}/></button></div>)}<small>Reorder and name the sections to create the exact document outline you need.</small></div><button className="create" onClick={saveStructure}><Plus size={15}/> Save structure</button>{notice&&<p className="template-notice">{notice}</p>}</div></div>}
function SettingsPage(){const [section,setSection]=useState('Details'),[saved,setSaved]=useState(false);const items=[['Details','General project information'],['Members','People and access'],['Issue types','Task categories'],['Workflows','Status transitions'],['Notifications','Delivery preferences'],['Documentation','Structures and review'],['AI settings','Instructions and style']];const save=()=>{setSaved(true);setTimeout(()=>setSaved(false),1800)};const content=section==='Documentation'?<DocumentationSettings/>:section==='Details'?<><label>Project name<input defaultValue="AI H Platform"/></label><label>Project key<input defaultValue="AIH"/></label><label>Description<textarea defaultValue="Central project management and documentation intelligence for modern engineering teams."/></label></>:section==='Members'?<div className="members-settings">{[['Ahmed Hassan','Project lead','AH'],['Sara Khalil','Developer','SA'],['Omar Nasser','Developer','OM'],['Lina Saad','Developer','LI'],['Yousef Ahmad','Developer','YO']].map(([name,role,initials])=><div key={name}><Avatar name={name} initials={initials}/><span><b>{name}</b><small>{role}</small></span><button className="secondary">Role <ChevronDown size={13}/></button></div>)}</div>:section==='AI settings'?<><label>Documentation style<select><option>Clear and technical</option><option>Concise</option><option>Detailed architecture</option></select></label><label>Default AI instructions<textarea defaultValue="Use clear technical language. Include implementation, configuration, testing, and security considerations when relevant."/></label></>:<div className="settings-placeholder"><Settings size={25}/><b>{section}</b><p>Configure {items.find(x=>x[0]===section)?.[1].toLowerCase()} for this project.</p></div>;return <section className="content settings-page"><div className="page-head"><div><div className="eyebrow">AI H PLATFORM</div><h1>Project settings</h1><p>Manage access, workflows, and documentation behavior.</p></div></div><div className="settings-layout"><aside className="settings-nav">{items.map(([name,description])=><button onClick={()=>setSection(name)} className={section===name?'active':''} key={name}><span>{name==='AI settings'?<Sparkles size={15}/>:<Settings size={15}/>}</span><div><b>{name}</b><small>{description}</small></div></button>)}</aside><section className="settings-panel"><div className="settings-panel-head"><div><h2>{section}</h2><p>{items.find(x=>x[0]===section)?.[1]}</p></div></div><div className="settings-form">{content}</div>{section!=='Documentation'&&<footer><span>{saved&&<><CheckCircle2 size={15}/> Changes saved</>}</span><button className="create" onClick={save}>Save changes</button></footer>}</section></div></section>}
function WorkList({tasks,open,create,mine,board}:{tasks:Task[],open:(t:Task)=>void,create:()=>void,mine:boolean,board:()=>void}){const [tab,setTab]=useState('Open');const visible=tasks.filter(t=>tab==='Open'?t.status!=='Done':tab==='Done'?t.status==='Done':t.status===tab);return <section className="content work-list"><div className="jira-title"><div className="project-icon small">AH</div><div><div className="eyebrow">AI H PLATFORM</div><h1>{mine?'My work':'All issues'}</h1></div><button className="project-switch">AI H Platform <ChevronDown size={14}/></button></div><div className="issue-tabs"><button className="selected">List</button><button onClick={board}>Board</button>{['Open','To Do','In Progress','Submit Work','Documentation Review','Done'].map(x=><button className={tab===x?'selected filter-tab':''} onClick={()=>setTab(x)} key={x}>{x}<span>{x==='Open'?tasks.filter(t=>t.status!=='Done').length:tasks.filter(t=>t.status===x).length}</span></button>)}</div><div className="jira-toolbar"><button className="filter-chip"><SlidersHorizontal size={14}/> Add filter</button><button className="filter-chip">Assignee: {mine?'Me':'Anyone'} <X size={13}/></button><button className="filter-chip">Status <ChevronDown size={13}/></button><button className="filter-chip">Priority <ChevronDown size={13}/></button><button className="more-filter">+ More</button><span className="toolbar-spacer"/><div className="inline-search"><Search size={15}/><input placeholder="Search issues"/></div><button className="icon-btn"><MoreHorizontal size={18}/></button><button className="create" onClick={create}><Plus size={16}/> Create</button></div><div className="issue-list jira-list"><div className="issue-row issue-row-header"><span><input type="checkbox" aria-label="Select all"/></span><span>KEY</span><b>SUMMARY</b><span>STATUS</span><span>PRIORITY</span><span>ASSIGNEE</span><span>DOCS</span></div>{visible.map(t=><button className="issue-row" onClick={()=>open(t)} key={t.id}><span className="check"><input type="checkbox" aria-label={'Select '+t.id} onClick={e=>e.stopPropagation()}/></span><span className="issue-id"><CircleDot size={15}/>{t.id}</span><b>{t.title}<small>{t.epic} · {t.labels.join(', ')}</small></b><Badge kind={'status-pill '+t.status.toLowerCase().replaceAll(' ','-')}>{t.status}</Badge><Badge kind={'priority '+t.priority.toLowerCase()}>{t.priority}</Badge><Avatar name={t.assignee} initials={t.initials}/><span className={'doc-state '+t.doc.toLowerCase().replaceAll(' ','-')}><Sparkles size={12}/>{t.doc}</span></button>)}</div>{visible.length===0&&<div className="empty-state"><CheckCircle2 size={28}/><b>Nothing here right now</b><span>Change the view or create a new issue.</span></div>}</section>}
function Sprints({tasks,open}:{tasks:Task[],open:(t:Task)=>void}){
 const sprints=[{id:12,name:'Sprint 12',dates:'Oct 7 – Oct 21',left:66,width:25,state:'Active',goal:'Ship secure authentication',done:'64%'},{id:11,name:'Sprint 11',dates:'Sep 23 – Oct 6',left:40,width:24,state:'Completed',goal:'Workspace foundations',done:'100%'},{id:10,name:'Sprint 10',dates:'Sep 9 – Sep 22',left:14,width:24,state:'Completed',goal:'Platform reliability',done:'100%'},{id:9,name:'Sprint 9',dates:'Aug 26 – Sep 8',left:0,width:12,state:'Completed',goal:'Planning & discovery',done:'100%'}];
 const [active,setActive]=useState(12);const sprint=sprints.find(s=>s.id===active)!;const sprintTasks=active===12?tasks:tasks.slice((12-active)*2,(12-active)*2+5);
 return <section className="content sprint-page"><div className="page-head"><div><div className="eyebrow">AI H PLATFORM</div><h1>Sprints</h1><p>Plan work across active and completed sprints.</p></div><div className="head-actions"><button className="secondary"><Calendar size={16}/> Timeline</button><button className="create"><Plus size={16}/> Create sprint</button></div></div><div className="sprint-summary"><div><Badge kind={sprint.state==='Active'?'blue':'approved'}>{sprint.state}</Badge><h2>{sprint.name}</h2><p>{sprint.goal}</p></div><div><span>DATES</span><b>{sprint.dates}</b></div><div><span>COMPLETION</span><b>{sprint.done}</b><div className="tiny-progress"><i style={{width:sprint.done}}/></div></div><button className="secondary">Sprint actions <ChevronDown size={14}/></button></div><section className="gantt"><div className="gantt-head"><b>Sprint timeline</b><span>Aug 26</span><span>Sep 9</span><span>Sep 23</span><span>Oct 7</span><span>Oct 21</span></div><div className="gantt-body">{sprints.map(s=><button className={'sprint-gantt-card '+(s.id===active?'selected':'')} key={s.id} style={{left:s.left+'%',width:s.width+'%'}} onClick={()=>setActive(s.id)}><div><b>{s.name}</b><Badge kind={s.state==='Active'?'blue':'approved'}>{s.state}</Badge></div><span>{s.dates}</span><i><em style={{width:s.done}}/></i></button>)}</div></section><div className="sprint-work-head"><div><h2>{sprint.name} board</h2><p>{sprintTasks.length} issues · {sprint.goal}</p></div><button className="secondary"><SlidersHorizontal size={15}/> Filter</button></div><div className="board sprint-board">{columns.map(status=><section className="kanban-col" key={status}><div className="col-head"><b>{status}</b><span>{sprintTasks.filter(task=>task.status===status).length}</span><MoreHorizontal size={16}/></div><div className="card-stack">{sprintTasks.filter(task=>task.status===status).map(task=><TaskCard key={task.id} task={task} open={()=>open(task)} drag={()=>{}} submit={()=>open(task)}/>)}</div></section>)}</div></section>
}
function Backlog({tasks,open,create}:{tasks:Task[],open:(t:Task)=>void,create:()=>void}){return <section className="content"><div className="page-head"><div><div className="eyebrow">AI H PLATFORM</div><h1>Backlog</h1><p>Plan, prioritize, and prepare work for upcoming sprints.</p></div><button className="create" onClick={create}><Plus size={17}/> Create issue</button></div><div className="backlog-layout"><aside className="epics"><h3>EPICS <Plus size={15}/></h3>{['Authentication','Workspace','Platform','Mobile'].map((x,i)=><button key={x}><span className={'epic-dot e'+i}/>{x}<small>{[5,7,8,3][i]}</small></button>)}</aside><div><div className="backlog-actions"><b>Sprint 12 <Badge kind="blue">Active</Badge></b><span>Oct 7 – Oct 21</span><button className="secondary">Start sprint</button></div><div className="issue-list">{tasks.map(t=><button className="issue-row" onClick={()=>open(t)} key={t.id}><CircleDot size={16}/><span className="issue-id">{t.id}</span><b>{t.title}</b><Badge kind={'priority '+t.priority.toLowerCase()}>{t.priority}</Badge><span className="row-labels">{t.labels.join(', ')}</span><Avatar name={t.assignee} initials={t.initials}/><span className="points">{t.points}</span></button>)}</div><div className="backlog-actions future"><b>Backlog</b><span>Unscheduled work</span></div></div></div></section>}
function Docs({tasks,projects,open}:{tasks:Task[],projects:string[],open:(t:Task)=>void}){const [search,setSearch]=useState(''),[expanded,setExpanded]=useState(projects),[selected,setSelected]=useState<Task|null>(null);const docs=tasks.filter(t=>t.doc!=='Not Started'&&t.title.toLowerCase().includes(search.toLowerCase()));const toggle=(name:string)=>setExpanded(current=>current.includes(name)?current.filter(x=>x!==name):[...current,name]);const visibleProjects=projects.filter(project=>docs.some(t=>(t.project||'AI H Platform')===project));return <section className="content doc-hierarchy-page"><div className="page-head"><div><div className="eyebrow">PROJECT KNOWLEDGE</div><h1>Documentation</h1><p>Created automatically from employee work submissions and grouped by project and task.</p></div></div><div className="doc-summary"><span><FolderKanban/><b>{visibleProjects.length}</b> projects</span><span><FileText/><b>{docs.length}</b> documents</span><span><CheckCircle2/><b>{docs.filter(t=>t.doc==='Approved').length}</b> approved</span></div><div className="doc-hierarchy-toolbar"><div className="inline-search"><Search size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search across all projects and documents"/></div><button className="secondary">Type <ChevronDown size={14}/></button><button className="secondary">Status <ChevronDown size={14}/></button></div><div className="hierarchy-layout"><aside className="document-tree"><div className="tree-label">PROJECTS &amp; DOCUMENTS</div>{visibleProjects.map(project=>{const projectDocs=docs.filter(t=>(t.project||'AI H Platform')===project);const isOpen=expanded.includes(project);return <div className="tree-project" key={project}><button className="tree-project-button" onClick={()=>toggle(project)}><ChevronDown className={isOpen?'':'closed'} size={15}/><span className="tree-project-icon"><FolderKanban size={15}/></span><b>{project}</b><small>{projectDocs.length}</small></button>{isOpen&&<div className="tree-children">{projectDocs.map(t=><button className={'tree-document '+(selected?.id===t.id?'selected':'')} onClick={()=>setSelected(t)} key={t.id}><FileText size={14}/><span><b>{t.title.replace(/^Implement |^Add |^Create |^Build /,'')}</b><small>{t.id}</small></span><Badge kind={'doc-state '+t.doc.toLowerCase().replaceAll(' ','-')}>{t.doc}</Badge></button>)}</div>}</div>})}</aside><section className="document-preview">{selected?<><div className="preview-heading"><span className="file-icon"><FileText size={17}/></span><div><span className="eyebrow">{selected.project||'AI H Platform'} · {selected.id}</span><h2>{selected.title.replace(/^Implement |^Add |^Create |^Build /,'')}</h2></div><Badge kind={'doc-state '+selected.doc.toLowerCase().replaceAll(' ','-')}>{selected.doc}</Badge></div><div className="preview-meta"><Avatar name={selected.assignee} initials={selected.initials}/><span>Authored by {selected.assignee}</span><em>•</em><span>Updated today</span></div><div className="preview-body"><h3>Overview</h3><p>{selected.description} This documentation was generated from the submitted work and is kept with its project’s technical knowledge.</p><h3>Included sections</h3><div className="section-pills">{['Implementation','Architecture','Configuration','Testing','Security'].map(x=><span key={x}>{x}</span>)}</div></div><footer><button className="secondary">Version history</button><button className="create" onClick={()=>open(selected)}>Open document <ArrowUpRight size={15}/></button></footer></>:<div className="tree-empty"><FileText size={30}/><b>Select a document</b><span>Choose a task document from the project hierarchy to preview it here.</span></div>}</section></div></section>}
function Reports(){return <section className="content"><div className="page-head"><div><div className="eyebrow">AI H PLATFORM</div><h1>Reports</h1><p>Project delivery and documentation insights.</p></div><button className="secondary"><Calendar size={16}/> Sprint 12</button></div><div className="report-grid"><section className="panel wide"><div className="panel-head"><div><h2>Sprint burndown</h2><p>Remaining work over time</p></div><Badge kind="blue">Sprint 12</Badge></div><div className="bar-chart">{[94,83,79,67,62,52,40,28,22,14].map((x,i)=><div key={i}><i style={{height:x+'%'}}/><small>{i+7}</small></div>)}</div></section><section className="panel"><div className="panel-head"><div><h2>Work distribution</h2><p>Current sprint workload</p></div></div><div className="distribution">{[['Ahmed',35],['Sara',25],['Omar',22],['Lina',18]].map(([x,n])=><div key={x as string}><span>{x}</span><i style={{width:n+'%'}}/><b>{n}%</b></div>)}</div></section><section className="panel wide coverage"><div className="panel-head"><div><h2>Documentation coverage</h2><p>AI H-specific delivery quality metric</p></div><Sparkles/></div><div className="coverage-numbers"><span><b>42</b>Completed tasks</span><span><b>38</b>Documented</span><span><b>4</b>Pending documentation</span></div><div className="coverage-line"><i/></div><b>90% documentation coverage</b></section><section className="panel"><div className="panel-head"><div><h2>Documentation activity</h2><p>Last 30 days</p></div></div>{[['Documents generated','38'],['Documents approved','31'],['Documents edited','17'],['Avg. generation time','48 sec']].map(([x,n])=><div className="report-stat" key={x}><span>{x}</span><b>{n}</b></div>)}</section></div></section>}
function Projects({open}:{open:(name:string)=>void}){let p=[['AI H Platform','AIH','Ahmed Hassan','64%','Sprint 12','38/42'],['E-Commerce System','ECS','Sara Khalil','47%','Checkout hardening','21/29'],['Mobile Banking','MBK','Omar Nasser','81%','Release 4.2','56/61'],['Internal Tools','INT','Lina Saad','32%','Automation suite','12/18']];return <section className="content"><div className="page-head"><div><div className="eyebrow">WORKSPACE</div><h1>Projects</h1><p>Manage work across all your teams and initiatives.</p></div><button className="create"><Plus size={17}/> Create project</button></div><div className="toolbar"><div className="inline-search"><Search size={16}/><input placeholder="Search projects"/></div><button className="secondary">All projects <ChevronDown size={14}/></button></div><div className="projects-table"><div className="project-row head"><span>PROJECT</span><span>LEAD</span><span>PROGRESS</span><span>ACTIVE SPRINT</span><span>DOCUMENTATION</span></div>{p.map(x=><button onClick={()=>open(x[0])} className="project-row" key={x[1]}><span className="project-name"><i>{x[1]}</i><b>{x[0]}<small>{x[1]} · {x[1]==='AIH'?'26':'14'} issues</small></b></span><span><Avatar name={x[2]} initials={x[2].split(' ').map(y=>y[0]).join('')}/>{x[2]}</span><span><div className="tiny-progress"><i style={{width:x[3]}}/></div>{x[3]}</span><span>{x[4]}</span><span><Badge kind="doc-state approved">{x[5]} documented</Badge></span></button>)}</div></section>}
function SearchPage({tasks,query,setQuery,open}:{tasks:Task[],query:string,setQuery:(x:string)=>void,open:(t:Task)=>void}){return <section className="content search-page"><div className="page-head"><div><div className="eyebrow">GLOBAL SEARCH</div><h1>Find anything</h1></div></div><div className="global-search"><Search/><input autoFocus value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search projects, issues, documents, and people"/><kbd>ESC</kbd></div><h3>ISSUES</h3>{tasks.slice(0,6).map(t=><button className="search-result" onClick={()=>open(t)} key={t.id}><CircleDot/><span><b>{t.id} · {t.title}</b><small>{t.epic} · Assigned to {t.assignee}</small></span><Badge kind={'doc-state '+t.doc.toLowerCase().replaceAll(' ','-')}>{t.doc}</Badge></button>)}<h3>DOCUMENTATION</h3><button className="search-result"><FileText/><span><b>Google OAuth authentication</b><small>AIH-102 · Updated today</small></span><Badge kind="doc-state needs-review">Needs Review</Badge></button></section>}
function Notifications({close}:{close:()=>void}){return <div className="notifications"><div className="panel-head"><b>Notifications</b><button onClick={close}><X size={16}/></button></div>{[['AI','Documentation generated for AIH-115','Just now'],['SA','Sara submitted work on AIH-108','48 min ago'],['OM','You were mentioned on AIH-109','2 hours ago'],['AH','Sprint 12 started','Yesterday']].map(([i,x,t])=><div className="notification" key={x}><Avatar name={i} initials={i}/><span><b>{x}</b><small>{t}</small></span></div>)}<button className="view-all">View all notifications</button></div>}
function IssueDrawer({task,tasks,close,submit,change}:{task:Task,tasks:Task[],close:()=>void,submit:()=>void,change:(x:Partial<Task>)=>void}){const dependencies=task.dependencies||[];return <><div className="scrim" onClick={close}/><aside className="drawer"><div className="drawer-head"><span className="issue-key"><CircleDot size={16}/>{task.id}</span><div><button className="icon-btn"><MoreHorizontal size={18}/></button><button className="icon-btn" onClick={close}><X size={19}/></button></div></div><div className="drawer-title"><h1>{task.title}</h1><div><button className="status-button" onClick={()=>change({status:task.status==='Done'?'To Do':'Done'})}><CheckCircle2 size={15}/>{task.status}<ChevronDown size={13}/></button><button className="secondary">{task.priority}<ChevronDown size={13}/></button></div></div><div className="drawer-body"><div className="issue-main"><h4>Description</h4><p>{task.description} The implementation should be production-ready, covered by tests, and follow existing platform conventions.</p><h4>Requirements</h4><ul><li>Implement the agreed technical solution.</li><li>Cover important error and edge cases.</li><li>Provide evidence and a clear work summary.</li></ul><section className="dependency-summary"><div className="dependency-heading"><Layers size={16}/><div><h4>Dependencies</h4><small>{dependencies.length?'This task has linked work.':'This task has no dependencies.'}</small></div></div>{dependencies.length?<div className="dependency-list">{dependencies.map(dependency=>{const linked=tasks.find(item=>item.id===dependency.issueId);const label=dependency.type==='blockedBy'?'Blocked by':dependency.type==='blocks'?'Blocks':'Related to';return <div className={'dependency-item '+dependency.type} key={dependency.type+dependency.issueId}><span>{label}</span><b>{dependency.issueId} · {linked?.title||'Linked task'}</b><Badge kind={linked?.status==='Done'?'doc-state approved':'doc-state needs-review'}>{linked?.status||'Unknown status'}</Badge></div>})}</div>:<p className="dependency-clear"><CheckCircle2 size={15}/> No other task must be completed before this one.</p>}</section>{task.submission&&<section className="employee-work"><div className="work-heading"><span><Upload size={15}/></span><div><h4>Employee submitted work</h4><small>{task.submission.submittedAt?'Submitted '+new Date(task.submission.submittedAt).toLocaleString():'Submitted work'}</small></div></div><h5>What was completed</h5><p>{task.submission.summary}</p><h5>Evidence</h5><div className="submitted-evidence">{task.submission.evidence.length?task.submission.evidence.map(item=><span key={item}><Paperclip size={13}/>{item}</span>):<small>No evidence attached.</small>}</div>{task.submission.repository&&<div className="submission-git"><b>Git</b><span>{task.submission.repository}</span><span>{task.submission.branch}</span><span>{task.submission.pullRequest}</span></div>}</section>}<h4>Attachments <button className="link-btn"><Paperclip size={14}/> Add</button></h4><div className="attachments"><span><FileText/>implementation-notes.md<small>12 KB</small></span><span><FileText/>auth-flow.png<small>248 KB</small></span></div><h4>Comments <button className="link-btn">Add comment</button></h4><div className="comment"><Avatar name="Sara" initials="SA"/><p><b>Sara Khalil</b><small>Yesterday</small>Looks good. Please include the edge cases around expired sessions.</p></div><div className="comment"><Avatar name="Ahmed" initials="AH"/><p><b>Ahmed Hassan</b><small>2 days ago</small>I’ve added the acceptance criteria and linked the epic.</p></div></div><aside className="issue-details"><h4>Details</h4>{[['Assignee',task.assignee],['Reporter','Ahmed Hassan'],['Sprint','Sprint 12'],['Epic',task.epic],['Story points',String(task.points)],['Due date','Oct 18, 2026'],['Documentation',task.doc]].map(([x,y])=><div key={x}><span>{x}</span><b>{y}</b></div>)}<h4>Labels</h4><div className="labels">{task.labels.map(x=><Badge key={x}>{x}</Badge>)}</div><h4>Activity</h4><div className="history"><p>Ahmed moved this to <b>{task.status}</b></p><small>Today, 9:42 AM</small><p>Task created</p><small>Oct 7, 2026</small></div></aside></div><footer>{task.status!=='Done'&&<button className="create" onClick={submit}><Upload size={16}/> Submit work</button>}<button className="secondary" onClick={close}>Close</button></footer></aside></>}
function CreateModal({close,add}:{close:()=>void,add:(t:Omit<Task,'id'|'initials'|'assignee'|'doc'|'epic'>)=>void}){const [title,setTitle]=useState('');return <><div className="scrim" onClick={close}/><div className="modal"><div className="modal-head"><div><h2>Create issue</h2><p>AI H Platform</p></div><button className="icon-btn" onClick={close}><X/></button></div><label>Issue type<select><option>Task</option><option>Story</option><option>Bug</option><option>Documentation</option></select></label><label>Summary<input autoFocus value={title} onChange={e=>setTitle(e.target.value)} placeholder="What needs to be done?"/></label><label>Description<textarea placeholder="Add context, requirements, or acceptance criteria..."/></label><div className="form-row"><label>Priority<select><option>Medium</option><option>High</option><option>Highest</option><option>Low</option></select></label><label>Story points<input defaultValue="3" type="number"/></label></div><footer><button className="secondary" onClick={close}>Cancel</button><button className="create" onClick={()=>title&&add({title,status:'To Do',priority:'Medium',points:3,labels:['platform'],description:'New issue created in AI H.'})}>Create issue</button></footer></div></>}
function Submission({task,close,generate}:{task:Task,close:()=>void,generate:(t:Task,work:WorkSubmission)=>void}){const [busy,setBusy]=useState(false),[evidence,setEvidence]=useState<string[]>([]),[summary,setSummary]=useState('Describe the work you completed, the result, and any decisions or findings.'),[aiPrompt,setAiPrompt]=useState(''),[documentStructure,setDocumentStructure]=useState('Technical implementation guide'),[customSections,setCustomSections]=useState(''),[useGit,setUseGit]=useState(false);const [repository,setRepository]=useState(''),[branch,setBranch]=useState(''),[pullRequest,setPullRequest]=useState('');const work={summary,evidence,aiPrompt,documentStructure,customSections,...(useGit?{repository,branch,pullRequest}:{})};return <><div className="scrim"/><div className="submission"><header><div><span className="issue-key">{task.id}</span><h1>Submit completed work</h1><p>Add the proof that fits your task—Git information is only needed for code-based work.</p></div><button className="icon-btn" onClick={close}><X/></button></header>{busy?<div className="generating"><Sparkles size={38}/><h2>Generating documentation</h2>{['Saving employee submission…','Reading your chosen format…','Applying your AI instructions…','Analyzing evidence…','Generating documentation…'].map((x,i)=><p key={x} className={i<3?'done':''}><CheckCircle2 size={16}/>{x}</p>)}</div>:<div className={'submission-grid '+(!useGit?'no-git':'')}><div><section className="task-context"><span>ORIGINAL TASK</span><h3>{task.title}</h3><p>{task.description}</p></section><label className="work-summary">What did you do?<textarea value={summary} onChange={e=>setSummary(e.target.value)}/></label><section className="structure-choice"><div><h3>Documentation format</h3><p>Choose the format that best fits this work.</p></div><select value={documentStructure} onChange={e=>setDocumentStructure(e.target.value)}><option>Technical implementation guide</option><option>Sales activity report</option><option>Business analysis report</option><option>Research findings report</option><option>Bug fix and root-cause report</option><option>Deployment runbook</option><option>Client handover guide</option><option>Custom structure</option></select>{documentStructure==='Custom structure'&&<textarea value={customSections} onChange={e=>setCustomSections(e.target.value)} placeholder="List the sections you want, for example: Context, Findings, Recommendation, Evidence, Next steps."/>}</section><label className="ai-instructions"><span><Sparkles size={15}/> Instructions for AI <em>Optional</em></span><textarea value={aiPrompt} onChange={e=>setAiPrompt(e.target.value)} placeholder="Example: Write this for a client, focus on business outcomes, and include recommendations."/><small>These instructions fine-tune the generated document.</small></label><section><h3>Evidence</h3><div className="evidence-grid">{['Screenshot','File','Code','Video','Audio'].map(x=><button key={x} onClick={()=>setEvidence(current=>current.some(item=>item.startsWith(x))?current.filter(item=>!item.startsWith(x)):[...current,x+' evidence'])}><Upload size={18}/>{evidence.some(item=>item.startsWith(x))?'Attached':x}</button>)}</div></section><label className="git-toggle"><input type="checkbox" checked={useGit} onChange={e=>setUseGit(e.target.checked)}/><span><b>This work includes GitHub / Git changes</b><small>Turn this on only for code-based work.</small></span></label></div>{useGit&&<aside className="git-card"><div><span className="git-logo">⌘</span><b>GitHub / Git</b><Badge kind="blue">Optional</Badge></div><label>Repository<input value={repository} onChange={e=>setRepository(e.target.value)} placeholder="organization/repository"/></label><label>Branch<input value={branch} onChange={e=>setBranch(e.target.value)} placeholder="feature/my-work"/></label><label>Pull request<input value={pullRequest} onChange={e=>setPullRequest(e.target.value)} placeholder="#123 Pull request title"/></label></aside>}</div>}<footer><button className="secondary" onClick={close}>Cancel</button><button className="create" disabled={!summary.trim()} onClick={()=>{setBusy(true);setTimeout(()=>generate(task,work),900)}}><Sparkles size={16}/> Submit &amp; generate documentation</button></footer></div></>}
function DocumentEditor({task,close,approve}:{task:Task,close:()=>void,approve:()=>void}){const [edit,setEdit]=useState(false),[notice,setNotice]=useState('');const text=`# ${task.title}\n\n## Overview\nThis document captures the implementation delivered for ${task.id}, including the technical approach, configuration, and validation.\n\n## Purpose\nThe change provides a reliable, secure path while keeping the integration maintainable for the engineering team.\n\n## Implementation\nThe feature uses a dedicated service boundary to validate requests, normalize provider responses, and persist the resulting state. Failure states are handled explicitly.\n\n## Architecture\nThe UI initiates the flow, the API validates the callback, and the identity service creates or links the user session. Audit events record authorization attempts.\n\n## Configuration\nSet provider credentials in the environment configuration. Redirect URLs must be registered for each environment.\n\n## Testing\nUnit tests cover callback handling and validation. Integration tests exercise successful sign-in, expired session, and denied-consent paths.\n\n## Security considerations\nState parameters are verified on callback. Refresh credentials are stored securely and rotated on use.`;return <div className="document-view"><header><div className="crumb"><span>Documentation</span><ChevronDown size={14}/><b>{task.id}</b></div><div className="top-actions"><button className="secondary" onClick={()=>setEdit(!edit)}>{edit?'Preview':'Edit'}</button><button className="secondary" onClick={()=>setNotice('AI improved the structure and added implementation details.')}><Sparkles size={15}/> Improve with AI</button><button className="secondary">Export</button><button className="create" onClick={approve}><CheckCircle2 size={16}/> Approve documentation</button><button className="icon-btn" onClick={close}><X/></button></div></header><div className="document-layout"><aside className="toc"><b>ON THIS PAGE</b>{['Overview','Purpose','Implementation','Architecture','Configuration','Testing','Security considerations'].map(x=><a href={'#'+x.replaceAll(' ','-')} key={x}>{x}</a>)}<hr/><small>Generated by AI H<br/>Based on submitted work</small></aside><article className="document"><span className="generated"><Sparkles size={14}/> AI-generated documentation</span>{edit?<textarea className="doc-edit" defaultValue={text}/>:text.split('\n\n').map((x,i)=>x.startsWith('# ')?<h1 key={i}>{x.slice(2)}</h1>:x.startsWith('## ')?<h2 id={x.slice(3).replaceAll(' ','-')} key={i}>{x.slice(3)}</h2>:<p key={i}>{x}</p>)}<div className="doc-footer">Last updated today at 10:24 AM · Version 1.0</div></article><aside className="ai-panel"><div><span className="ai-orb"><Sparkles/></span><h3>AI H Assistant</h3><p>Refine this documentation with AI.</p></div>{['Make this more technical','Add implementation details','Explain the API','Improve the structure','Generate examples','Make it shorter'].map(x=><button key={x} onClick={()=>setNotice('AI H updated the document: '+x)}>{x}<ArrowUpRight size={13}/></button>)}<div className="ask"><input placeholder="Ask AI…"/><Send size={15}/></div>{notice&&<p className="ai-response"><Bot size={15}/>{notice}</p>}</aside></div></div>}
createRoot(document.getElementById('root')!).render(<App/>);
